"""Working demo for this book record: full reader + HTML exporter.
Run:  python3 book_demo.py              (prints the whole book)
      python3 book_demo.py 3            (prints chapter 3 only)
      python3 book_demo.py search WORD  (finds WORD across chapters)
      python3 book_demo.py html         (writes book.html)
"""
import json, sys, html as _h

BOOK = {'title': 'Engines of Hope', 'author': 'Signature original', 'genre': 'Asteroid Miners', 'chapters': [{'n': 1, 'title': 'Launch', 'text': "Navigator Bo Tak ran the numbers with grease on their hands and worry in their eyes. 'Pirate Queen Vex has three ships in the drift,' they said. 'If we burn hard, we can make it. If we burn hard, everyone will see us.'\n\nCommander Sera Ilsa gave the order anyway. The engines lit, the deck hummed, and the ship leapt toward a quantum compass with the Valtor Nebula falling behind. Some cargoes, Commander Sera Ilsa knew, are worth the whole sky.\n\nThe klaxon woke Commander Sera Ilsa before the dawn cycle. On the viewscreen, the Valtor Nebula glittered — and tumbling toward it, broadcasting on all bands, was a quantum compass. 'Navigator Bo Tak,' Commander Sera Ilsa said, 'plot an intercept. Quietly.'"}, {'n': 2, 'title': 'The Chart Unfolds', 'text': "In the quiet after, Commander Sera Ilsa played the starlog again. The voice — old, tired, kind — said: 'Whoever finds this, the Valtor Nebula needs you. Hurry.' Commander Sera Ilsa set the course and did not look back.\n\nThe crew voted — that was Commander Sera Ilsa's rule, always a vote before a suicide run. Every hand went up. Navigator Bo Tak grinned. 'We didn't sign on for safe,' they said.\n\n'It's a map,' breathed Commander Sera Ilsa, 'and a warning.' The route it drew cut through the worst of the drift: plasma storms, minefields, and the patrol lanes of Pirate Queen Vex."}, {'n': 3, 'title': 'Storm Season', 'text': "Through the fire they saw it: Pirate Queen Vex's flagship, waiting in the storm's eye like a spider. 'They knew the route,' Commander Sera Ilsa said. 'Someone sold the starlog.' The betrayal sat cold in their stomach.\n\nThe battle was short and ugly. Commander Sera Ilsa used the storm itself as a weapon, luring the flagship into a plasma surge that stripped its shields. They escaped in the glare, hull scorched, crew cheering raggedly.\n\nAfterward, Commander Sera Ilsa looked at each face on the bridge and said it plainly: 'There's a traitor aboard. I don't know who. But a quantum compass goes to the Valtor Nebula — with all of us, or with whoever's left.'"}, {'n': 4, 'title': "The Traitor's Price", 'text': "The traitor showed themselves at the third waypoint: the signal officer, paid in promises by Pirate Queen Vex. They seized a quantum compass and ran for the escape pod with Pirate Queen Vex's ships closing in.\n\nCommander Sera Ilsa laughed for the first time in days. 'All this way,' they said, 'and we were carrying the lock, not the treasure.' Navigator Bo Tak was already calculating the wake-up sequence.\n\nThen a quantum compass spoke — fully, at last. Not a map but a key, and not to a place but to a shield: an ancient defense grid sleeping around the Valtor Nebula, the only thing that could stop Pirate Queen Vex's fleet."}, {'n': 5, 'title': 'The Grid Awakens', 'text': "The duel was legend before it ended: two ships in the fire-light, neither yielding, until Commander Sera Ilsa did the impossible — dove through the grid's own gate, which a quantum compass held open, and watched Pirate Queen Vex break against the shield they could not see.\n\nNavigator Bo Tak fed a quantum compass into the ancient console. For a heartbeat nothing happened — then the sky caught fire, a lattice of light wrapping the Valtor Nebula like a held breath. Pirate Queen Vex's vanguard shattered against it like waves on rock.\n\nThe flagship came on anyway, and Commander Sera Ilsa met it ship to ship above the burning sky. It was Pirate Queen Vex themselves on the viewscreen, offering one last deal. Commander Sera Ilsa answered with the engines at full burn."}, {'n': 6, 'title': 'Home Signal', 'text': "Navigator Bo Tak was offered an admiralty and laughed in the committee's face. 'I have a ship,' they said. It was the highest compliment the crew had ever heard.\n\nThey landed at the Valtor Nebula to crowds and bells. The old voice from the starlog had belonged to the grid's last keeper, dead a hundred years; a quantum compass was their final message. Commander Sera Ilsa laid it in the memorial with honors.\n\nCommander Sera Ilsa stood on the hull at sunset, watching the Valtor Nebula turn below. home is the crew — the stars had taught it, and the crew had proved it, and the grid would remember it."}]}

def word_count():
    return sum(len(c["text"].split()) for c in BOOK["chapters"])

def print_book(ch=None):
    print("=" * 64)
    print(BOOK["title"].upper(), "\nby", BOOK["author"], "-", BOOK["genre"])
    print("=" * 64)
    for c in BOOK["chapters"]:
        if ch and c["n"] != ch:
            continue
        print("\n\nCHAPTER %d: %s\n%s" % (c["n"], c["title"], "-" * 40))
        print(c["text"])
    print("\n[%d words, %d chapters — complete]" % (word_count(), len(BOOK["chapters"])))

def search(word):
    w = word.lower()
    for c in BOOK["chapters"]:
        for i, para in enumerate(c["text"].split("\n\n")):
            if w in para.lower():
                print("[ch %d, para %d] %s..." % (c["n"], i + 1, para[:160].replace("\n", " ")))

def write_html(path="book.html"):
    parts = ["<html><head><meta charset='utf-8'><title>%s</title></head><body>" % _h.escape(BOOK["title"])]
    parts.append("<h1>%s</h1><p><i>by %s — %s</i></p>" % (_h.escape(BOOK["title"]), _h.escape(BOOK["author"]), _h.escape(BOOK["genre"])))
    for c in BOOK["chapters"]:
        parts.append("<h2>Chapter %d: %s</h2>" % (c["n"], _h.escape(c["title"])))
        for para in c["text"].split("\n\n"):
            parts.append("<p>%s</p>" % _h.escape(para))
    parts.append("</body></html>")
    open(path, "w").write("\n".join(parts))
    print("wrote", path)

if __name__ == "__main__":
    a = sys.argv[1:]
    if a and a[0] == "html":
        write_html()
    elif len(a) >= 2 and a[0] == "search":
        search(a[1])
    elif a and a[0].isdigit():
        print_book(int(a[0]))
    else:
        print_book()

